import { createHash } from 'node:crypto';

/**
 * Generated files carry a header with the sha256 of their body, so a later
 * regeneration can tell an untouched generated file from one a person edited
 * (ADR-017: regeneration never overwrites hand-written code).
 */

export const GENERATED_MARKER = '@generated by `protoyard generate`';
const HASH_LINE = /@hash sha256:([0-9a-f]{64})/;

export type CommentStyle = 'ts' | 'svelte';

export function sha256(text: string): string {
  return createHash('sha256').update(text).digest('hex');
}

/** Prepends the generated header (marker + body hash) in the file's comment syntax. */
export function withHeader(body: string, style: CommentStyle): string {
  const hash = sha256(body);
  const lines = [
    `${GENERATED_MARKER} from blueprint.json. Do not edit: regenerate instead.`,
    'Hand-written code belongs outside src/generated/.',
    `@hash sha256:${hash}`,
  ];
  const header =
    style === 'svelte'
      ? `<!--\n  ${lines.join('\n  ')}\n-->\n`
      : `/**\n * ${lines.join('\n * ')}\n */\n`;
  return header + body;
}

export interface HeaderCheck {
  generated: boolean;
  /** True when the body still matches the hash in its header. */
  intact: boolean;
}

/** Reads a file's generated header and checks the body against its hash. */
export function checkHeader(text: string): HeaderCheck {
  const match = HASH_LINE.exec(text);
  if (!text.includes(GENERATED_MARKER) || !match) return { generated: false, intact: false };
  const end = text.startsWith('<!--') ? text.indexOf('-->\n') + 4 : text.indexOf(' */\n') + 4;
  return { generated: true, intact: end > 3 && sha256(text.slice(end)) === match[1] };
}
